import { terminalPaneExtension, terminalTabPaneExtension } from './terminal-pane.js';

let paneRegistered = false;

export function registerGhosttyTerminalPanes(): boolean {
  const webApi = (globalThis as any).__piclaw_web;
  if (!webApi || typeof webApi.registerPane !== 'function') return false;
  webApi.registerPane(terminalPaneExtension);
  webApi.registerPane(terminalTabPaneExtension);
  paneRegistered = true;
  console.info('[ghostty-terminal] registered Ghostty terminal panes');
  return true;
}

try {
  registerGhosttyTerminalPanes();
  if (typeof window !== 'undefined') {
    window.addEventListener('piclaw:addons-loaded', () => {
      try { registerGhosttyTerminalPanes(); } catch {}
    });
  }
} catch (error) {
  console.warn('[ghostty-terminal] pane registration failed', error);
}

export function isGhosttyTerminalRegistered(): boolean {
  return paneRegistered;
}
